# Configuration Template
# This file shows the expected configuration structure
# DO NOT edit this file. Copy .env.example to .env and configure there.

import os
from dotenv import load_dotenv

# Load environment variables from .env file
load_dotenv()

# Database Configuration
DB_CONFIG = {
    'host': os.getenv('DB_HOST', 'localhost'),
    'user': os.getenv('DB_USER'),  # Required
    'password': os.getenv('DB_PASSWORD'),  # Required
    'database': os.getenv('DB_NAME', 'Hotel_Management'),
    'port': int(os.getenv('DB_PORT', 3306))
}

# Application Settings
APP_TITLE = os.getenv('APP_TITLE', 'Hotel Management System')
APP_ICON = os.getenv('APP_ICON', '🏨')

# Color Theme
PRIMARY_COLOR = os.getenv('PRIMARY_COLOR', '#667eea')
SECONDARY_COLOR = os.getenv('SECONDARY_COLOR', '#764ba2')

# Validation
if not DB_CONFIG['user']:
    raise ValueError("DB_USER environment variable is required. Please set it in .env file.")
if not DB_CONFIG['password']:
    raise ValueError("DB_PASSWORD environment variable is required. Please set it in .env file.")
